using ll = long long;
ll exgcd(ll a, ll b, ll& x, ll& y) {
    if (!b) { x = 1; y = 0; return a; }
    ll g = exgcd(b, a % b, y, x);
    y -= a / b * x;
    return g;
}
// 求解 x ≡ a[i] (mod m[i])，模数可不互质
// 返回最小非负解；无解返回 -1
ll excrt(const vector<ll>& a, const vector<ll>& m) {
    int n = (int)a.size();
    ll x = (a[0] % m[0] + m[0]) % m[0], M = m[0]; // 当前合并结果 x ≡ x (mod M)
    for (int i = 1; i < n; i++) {
        ll p, q;
        ll g = exgcd(M, m[i], p, q);        // 解 M·p + m[i]·q = gcd(M, m[i])
        ll c = ((a[i] - x) % m[i] + m[i]) % m[i]; // 差 a[i] - x（规范化到 [0, m[i])）
        if (c % g != 0) return -1;          // 无解：差不能被 gcd 整除
        ll t = m[i] / g;
        p = (p % t + t) % t;                // 先缩到 [0, t)，防溢出
        ll k = (c / g % t) * p % t;         // k 满足 x + M·k ≡ a[i] (mod m[i])
        x += M * k;
        M = M / g * m[i];                   // 新模数 = lcm(M, m[i])，先除后乘
        x = (x % M + M) % M;
    }
    return x;
}
